option.value:
/* Dashboard Header */
.dashboard-header {
  background: linear-gradient(135deg, var(--primary-50) 0%, var(--gray-50) 100%);
  border-bottom: 1px solid var(--gray-200);
  padding: var(--space-8) 0;
}

.header-content {
  display: flex;
  justify-content: space-between;
  align-items: center;

  h1 {
    font-size: var(--text-4xl);
    margin-bottom: var(--space-2);
  }

  p {
    color: var(--gray-600);
    font-size: var(--text-lg);
  }
}

/* Dashboard Layout */
.dashboard-layout {
  display: grid;
  grid-template-columns: 280px 1fr;
  gap: var(--space-8);
  padding: var(--space-8) 0;
  min-height: calc(100vh - 250px);
}

/* Sidebar */
.dashboard-sidebar {
  position: sticky;
  top: 100px;
  height: fit-content;
}

.sidebar-nav {
  background: white;
  border-radius: var(--radius-2xl);
  border: 2px solid var(--gray-200);
  padding: var(--space-4);
  box-shadow: var(--shadow-sm);
}

.nav-item {
  display: flex;
  align-items: center;
  gap: var(--space-3);
  width: 100%;
  padding: var(--space-4);
  border: none;
  background: transparent;
  border-radius: var(--radius-lg);
  font-weight: var(--font-semibold);
  color: var(--gray-700);
  cursor: pointer;
  transition: all var(--transition-fast);
  margin-bottom: var(--space-2);

  svg {
    flex-shrink: 0;
    color: var(--gray-500);
    transition: color var(--transition-fast);
  }

  span {
    flex: 1;
    text-align: left;
  }

  &:hover {
    background: var(--gray-50);
    color: var(--gray-900);

    svg {
      color: var(--primary-600);
    }
  }

  &.active {
    background: linear-gradient(135deg, var(--primary-600), var(--primary-500));
    color: white;

    svg {
      color: white;
    }

    .badge-count {
      background: rgba(255, 255, 255, 0.3);
      color: white;
    }
  }

  &.btn-create {
    background: var(--primary-600);
    color: white;
    margin-top: var(--space-4);

    svg {
      color: white;
    }

    &:hover {
      background: var(--primary-500);
      transform: translateY(-2px);
      box-shadow: var(--shadow-lg);
    }
  }
}

.badge-count {
  padding: 4px 8px;
  background: var(--gray-100);
  color: var(--gray-700);
  border-radius: var(--radius-full);
  font-size: var(--text-xs);
  font-weight: var(--font-bold);
}

/* Main Content */
.dashboard-main {
  background: white;
  border-radius: var(--radius-2xl);
  border: 2px solid var(--gray-200);
  box-shadow: var(--shadow-sm);
  min-height: 500px;
}

.dashboard-content {
  padding: var(--space-8);

  h2 {
    font-size: var(--text-3xl);
    margin-bottom: var(--space-6);
  }

  h3 {
    font-size: var(--text-2xl);
    margin-bottom: var(--space-4);
    margin-top: var(--space-8);
  }
}

.content-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: var(--space-6);

  h2 {
    margin-bottom: 0;
  }
}

/* Stats Grid */
.stats-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: var(--space-6);
  margin-bottom: var(--space-8);
}

.stat-card {
  display: flex;
  gap: var(--space-4);
  padding: var(--space-6);
  background: white;
  border: 2px solid var(--gray-200);
  border-radius: var(--radius-xl);
  transition: all var(--transition-base);

  &:hover {
    border-color: var(--primary-300);
    transform: translateY(-4px);
    box-shadow: var(--shadow-xl);
  }
}

.stat-icon {
  width: 56px;
  height: 56px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: var(--radius-xl);
  flex-shrink: 0;
}

.stat-content {
  flex: 1;
}

.stat-label {
  font-size: var(--text-sm);
  color: var(--gray-600);
  font-weight: var(--font-semibold);
  text-transform: uppercase;
  letter-spacing: 0.5px;
  margin-bottom: var(--space-2);
}

.stat-value {
  font-size: var(--text-4xl);
  font-weight: var(--font-bold);
  color: var(--gray-900);
}

/* Quick Actions */
.quick-actions {
  margin-top: var(--space-8);
}

.actions-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: var(--space-6);
}

.action-card {
  padding: var(--space-6);
  background: white;
  border: 2px solid var(--gray-200);
  border-radius: var(--radius-xl);
  cursor: pointer;
  transition: all var(--transition-base);
  text-align: center;

  svg {
    color: var(--primary-600);
    margin-bottom: var(--space-4);
  }

  h4 {
    font-size: var(--text-lg);
    margin-bottom: var(--space-2);
    color: var(--gray-900);
  }

  p {
    font-size: var(--text-sm);
    color: var(--gray-600);
  }

  &:hover {
    border-color: var(--primary-500);
    background: var(--primary-50);
    transform: translateY(-4px);
    box-shadow: var(--shadow-xl);

    svg {
      transform: scale(1.1);
    }
  }
}

/* Spaces Grid */
.spaces-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(320px, 1fr));
  gap: var(--space-6);
}

.space-card-dashboard {
  background: white;
  border: 2px solid var(--gray-200);
  border-radius: var(--radius-xl);
  overflow: hidden;
  transition: all var(--transition-base);

  &:hover {
    border-color: var(--primary-300);
    box-shadow: var(--shadow-xl);
    transform: translateY(-4px);
  }
}

.space-card-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: var(--space-4);
  background: var(--gray-50);
  border-bottom: 1px solid var(--gray-200);
}

.space-card-actions {
  display: flex;
  gap: var(--space-2);
}

.btn-icon {
  width: 36px;
  height: 36px;
  display: flex;
  align-items: center;
  justify-content: center;
  border: none;
  background: white;
  border-radius: var(--radius-lg);
  cursor: pointer;
  transition: all var(--transition-fast);
  color: var(--gray-700);

  &:hover {
    background: var(--gray-100);
    color: var(--primary-600);
  }

  &.btn-danger {
    &:hover {
      background: var(--error-light);
      color: var(--error);
    }
  }
}

.space-card-body {
  padding: var(--space-5);

  h3 {
    font-size: var(--text-xl);
    margin-bottom: var(--space-3);
    margin-top: 0;
  }
}

.space-address {
  color: var(--gray-600);
  font-size: var(--text-sm);
  margin-bottom: var(--space-4);
}

.space-features {
  display: flex;
  gap: var(--space-4);
  margin-bottom: var(--space-4);
  font-size: var(--text-sm);
  color: var(--gray-700);
}

.space-price {
  display: flex;
  align-items: baseline;
  gap: var(--space-2);
  padding: var(--space-3);
  background: var(--gray-50);
  border-radius: var(--radius-lg);
  margin-bottom: var(--space-4);

  strong {
    font-size: var(--text-2xl);
    color: var(--primary-600);
  }

  span {
    color: var(--gray-600);
  }
}

/* Space Form */
.space-form {
  max-width: 800px;
}

.form-section {
  margin-bottom: var(--space-8);
  padding-bottom: var(--space-8);
  border-bottom: 1px solid var(--gray-200);

  h3 {
    font-size: var(--text-xl);
    margin-bottom: var(--space-4);
    margin-top: 0;
  }
}

.form-group {
  margin-bottom: var(--space-5);
}

.form-label {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  font-size: var(--text-sm);
  font-weight: var(--font-bold);
  color: var(--gray-900);
  margin-bottom: var(--space-2);
  text-transform: uppercase;
  letter-spacing: 0.5px;

  svg {
    color: var(--primary-600);
  }
}

.form-input {
  width: 100%;
  padding: var(--space-4);
  font-size: var(--text-base);
  color: var(--gray-900);
  background: var(--gray-50);
  border: 2px solid var(--gray-200);
  border-radius: var(--radius-lg);
  transition: all var(--transition-fast);
  font-weight: var(--font-medium);
  font-family: inherit;

  &:hover {
    background: white;
    border-color: var(--gray-300);
  }

  &:focus {
    outline: none;
    background: white;
    border-color: var(--primary-500);
    box-shadow: 0 0 0 4px rgba(244, 63, 94, 0.1);
    transform: translateY(-1px);
  }

  &::placeholder {
    color: var(--gray-400);
    font-weight: var(--font-normal);
  }
}

textarea.form-input {
  resize: vertical;
  min-height: 100px;
}

.form-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-4);
}

.form-hint {
  display: block;
  margin-top: var(--space-2);
  font-size: var(--text-xs);
  color: var(--gray-500);
  font-weight: var(--font-medium);
}

.form-error {
  display: block;
  margin-top: var(--space-2);
  font-size: var(--text-xs);
  color: var(--error);
  font-weight: var(--font-semibold);
}

.form-actions {
  display: flex;
  justify-content: flex-end;
  gap: var(--space-4);
  margin-top: var(--space-8);
  padding-top: var(--space-6);
  border-top: 1px solid var(--gray-200);
}

/* Amenities Selector */
.amenities-selector {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
  gap: var(--space-3);
}

.amenity-checkbox {
  display: flex;
  align-items: center;
  gap: var(--space-3);
  padding: var(--space-3);
  border: 2px solid var(--gray-200);
  border-radius: var(--radius-lg);
  cursor: pointer;
  transition: all var(--transition-fast);

  input[type="checkbox"] {
    width: 20px;
    height: 20px;
    cursor: pointer;
  }

  &:hover {
    border-color: var(--primary-300);
    background: var(--primary-50);
  }

  input[type="checkbox"]:checked + .amenity-label {
    color: var(--primary-600);
    font-weight: var(--font-semibold);
  }
}

.amenity-label {
  font-size: var(--text-sm);
  color: var(--gray-700);
}

/* Alerts */
.alert {
  display: flex;
  align-items: center;
  gap: var(--space-3);
  padding: var(--space-4);
  border-radius: var(--radius-lg);
  margin-bottom: var(--space-6);

  svg {
    flex-shrink: 0;
  }
}

.alert-error {
  background: var(--error-light);
  color: var(--error);
  border: 2px solid var(--error);
}

/* Empty State */
.empty-state {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: var(--space-20);
  text-align: center;

  svg {
    color: var(--gray-400);
    margin-bottom: var(--space-6);
  }

  h3 {
    color: var(--gray-900);
    margin-bottom: var(--space-3);
  }

  p {
    color: var(--gray-600);
    margin-bottom: var(--space-6);
    max-width: 400px;
  }
}

/* Loading */
.loading-container {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: var(--space-20);

  p {
    margin-top: var(--space-4);
    color: var(--gray-600);
  }
}

/* Recent Spaces List */
.spaces-list-compact {
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
}

.space-item-compact {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: var(--space-4);
  background: var(--gray-50);
  border-radius: var(--radius-lg);
  transition: all var(--transition-fast);

  &:hover {
    background: var(--gray-100);
  }
}

.space-info-compact {
  h4 {
    font-size: var(--text-base);
    margin-bottom: var(--space-1);
    margin-top: 0;
  }

  p {
    font-size: var(--text-sm);
    color: var(--gray-600);
  }
}

/* Modal */
.modal-overlay {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: rgba(0, 0, 0, 0.5);
  backdrop-filter: blur(4px);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 9999;
  padding: var(--space-4);
  animation: fadeIn 0.2s ease-out;
}

.modal {
  background: white;
  border-radius: var(--radius-2xl);
  max-width: 500px;
  width: 100%;
  box-shadow: var(--shadow-2xl);
  animation: slideUp 0.3s ease-out;
}

.modal-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: var(--space-6);
  border-bottom: 1px solid var(--gray-200);

  h3 {
    margin: 0;
    font-size: var(--text-2xl);
  }
}

.modal-close {
  width: 40px;
  height: 40px;
  border-radius: var(--radius-full);
  border: none;
  background: var(--gray-100);
  color: var(--gray-700);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: all var(--transition-fast);

  &:hover {
    background: var(--gray-200);
    color: var(--gray-900);
  }
}

.modal-body {
  padding: var(--space-6);

  p {
    margin-bottom: var(--space-4);
    color: var(--gray-700);
  }
}

.modal-warning {
  color: var(--error);
  font-weight: var(--font-semibold);
}

.modal-footer {
  display: flex;
  justify-content: flex-end;
  gap: var(--space-3);
  padding: var(--space-6);
  border-top: 1px solid var(--gray-200);
}

/* Spaces Filters (estilo Airbnb) */
.spaces-filters {
  display: flex;
  gap: var(--space-3);
  margin-bottom: var(--space-6);
  padding: var(--space-4);
  background: white;
  border-radius: var(--radius-xl);
  border: 2px solid var(--gray-200);
  overflow-x: auto;

  &::-webkit-scrollbar {
    height: 6px;
  }

  &::-webkit-scrollbar-track {
    background: var(--gray-100);
    border-radius: 3px;
  }

  &::-webkit-scrollbar-thumb {
    background: var(--gray-400);
    border-radius: 3px;
  }
}

.filter-btn {
  padding: 10px 20px;
  border: 2px solid var(--gray-200);
  background: white;
  border-radius: var(--radius-full);
  font-size: var(--text-sm);
  font-weight: var(--font-semibold);
  color: var(--gray-700);
  cursor: pointer;
  transition: all var(--transition-fast);
  white-space: nowrap;

  &:hover {
    background: var(--gray-50);
    border-color: var(--gray-300);
    transform: translateY(-1px);
  }

  &.active {
    background: var(--gray-900);
    color: white;
    border-color: var(--gray-900);
  }
}

.btn-warning {
  &:hover {
    background: var(--warning-light);
    color: var(--warning);
  }
}

/* Badges */
.badge {
  display: inline-block;
  padding: 6px 12px;
  font-size: var(--text-xs);
  font-weight: var(--font-bold);
  border-radius: var(--radius-full);
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.badge-success {
  background: var(--success-light);
  color: var(--success);
}

.badge-warning {
  background: var(--warning-light);
  color: var(--warning);
}

.badge-info {
  background: var(--info-light);
  color: var(--info);
}

.badge-danger {
  background: var(--error-light);
  color: var(--error);
}

.badge-secondary {
  background: var(--gray-200);
  color: var(--gray-700);
}

.badge-default {
  background: var(--gray-100);
  color: var(--gray-600);
}

/* Responsive */
@media (max-width: 1024px) {
  .dashboard-layout {
    grid-template-columns: 1fr;
  }

  .dashboard-sidebar {
    position: relative;
    top: 0;
  }

  .sidebar-nav {
    display: flex;
    gap: var(--space-2);
    overflow-x: auto;
    padding: var(--space-3);

    .nav-item {
      margin-bottom: 0;
      white-space: nowrap;
    }
  }
}

@media (max-width: 768px) {
  .header-content {
    flex-direction: column;
    gap: var(--space-4);
    text-align: center;
  }

  .stats-grid {
    grid-template-columns: 1fr;
  }

  .spaces-grid {
    grid-template-columns: 1fr;
  }

  .form-row {
    grid-template-columns: 1fr;
  }

  .actions-grid {
    grid-template-columns: 1fr;
  }

  .amenities-selector {
    grid-template-columns: 1fr;
  }
}

/* Dashboard Header */
